const J = (o, s = 200) => new Response(JSON.stringify(o), { status: s, headers: { "content-type": "application/json", "cache-control": "no-store" } });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const same = (a, b) => { if (a.length !== b.length) return false; let d = 0; for (let i = 0; i < a.length; i++) d |= a.charCodeAt(i) ^ b.charCodeAt(i); return d === 0; };

function authed(req, env) {
  if (!env.ADMIN_USER || !env.ADMIN_PASS) return null;
  const h = req.headers.get("authorization") || "";
  if (!h.startsWith("Basic ")) return false;
  let d;
  try { d = new TextDecoder().decode(Uint8Array.from(atob(h.slice(6)), (c) => c.charCodeAt(0))); } catch (e) { return false; }
  const i = d.indexOf(":");
  return same(d.slice(0, i).toLowerCase(), env.ADMIN_USER.toLowerCase()) && same(d.slice(i + 1), env.ADMIN_PASS);
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (!url.pathname.startsWith("/api")) {
      if (url.pathname === "/" || url.pathname === "/index.html") {
        return new Response(HTML, { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "public, max-age=60", "x-content-type-options": "nosniff", "referrer-policy": "strict-origin-when-cross-origin" } });
      }
      return new Response("No encontrado", { status: 404 });
    }
    const parts = url.pathname.replace(/^\/api\/?/, "").split("/");
    const m = request.method;
    const B = env.BUCKET;
    if (!B) return J({ error: "falta conectar el bucket R2" }, 500);

    if (parts[0] === "data" && m === "GET") {
      const o = await B.get("state.json");
      if (!o) return J({}, 404);
      return new Response(o.body, { headers: { "content-type": "application/json", "cache-control": "public, max-age=20" } });
    }
    if (parts[0] === "img" && m === "GET") {
      const id = parts[1] || "";
      if (!/^[a-f0-9-]{36}$/.test(id)) return new Response("", { status: 404 });
      const sfx = parts[2] === "s" ? ".s" : parts[2] === "m" ? ".m" : "";
      let o = sfx ? await B.get("img/" + id + sfx) : null;
      if (!o) o = await B.get("img/" + id);
      if (!o) return new Response("", { status: 404 });
      return new Response(o.body, { headers: { "content-type": (o.httpMetadata && o.httpMetadata.contentType) || "image/jpeg", "cache-control": "public, max-age=31536000, immutable", "x-content-type-options": "nosniff" } });
    }

    const a = authed(request, env);
    if (a === null) return J({ error: "sin configurar" }, 500);
    if (!a) { await sleep(700); return J({ error: "no autorizado" }, 401); }

    if (parts[0] === "login" && m === "POST") return J({ ok: 1 });
    if (parts[0] === "data" && m === "PUT") {
      const txt = await request.text();
      if (txt.length > 2000000) return J({ error: "datos muy grandes" }, 413);
      let b;
      try { b = JSON.parse(txt); } catch (e) { return J({ error: "datos inválidos" }, 400); }
      if (!b || !Array.isArray(b.prods)) return J({ error: "datos inválidos" }, 400);
      delete b.auth;
      await B.put("state.json", JSON.stringify(b), { httpMetadata: { contentType: "application/json" } });
      return J({ ok: 1 });
    }
    if (parts[0] === "img" && m === "POST") {
      const buf = await request.arrayBuffer();
      if (buf.byteLength > 9000000) return J({ error: "imagen muy grande" }, 413);
      let t = (request.headers.get("content-type") || "").toLowerCase();
      if (!/^image\/(jpeg|png|webp|gif)$/.test(t)) t = "image/jpeg";
      const kind = url.searchParams.get("kind");
      if (kind === "thumb" || kind === "mid") {
        const id = url.searchParams.get("id") || "";
        if (!/^[a-f0-9-]{36}$/.test(id)) return J({ error: "id inválido" }, 400);
        await B.put("img/" + id + (kind === "thumb" ? ".s" : ".m"), buf, { httpMetadata: { contentType: "image/jpeg" } });
        return J({ ok: 1 });
      }
      const id = crypto.randomUUID();
      await B.put("img/" + id, buf, { httpMetadata: { contentType: t } });
      return J({ id, url: "/api/img/" + id });
    }
    return J({ error: "no encontrado" }, 404);
  },
};
